import { useState } from 'react'

import { Dialog } from '@jbrowse/core/ui'
import { DialogContent } from '@mui/material'
import { observer } from 'mobx-react'

import MonospaceTextField from './MonospaceTextField.tsx'
import UcscQueryActions from './UcscQueryActions.tsx'
import UcscQueryFields from './UcscQueryFields.tsx'
import UcscQueryStatus from './UcscQueryStatus.tsx'
import {
  DEFAULT_BLAT_URL,
  MINIMUM_BLAT_LENGTH,
  blatQueryProblem,
  blatResidueCount,
  buildBlatBody,
  parseBlatResponse,
  parseFastaRecords,
  pslToFeatures,
  queryLabel,
} from './blatQuery.ts'
import { parseQuerySequences, pslToSam } from './pslToSam.ts'
import { spliceHits } from './spliceJunctions.ts'
import {
  canRenderAlignments,
  referenceReader,
  viewedAssembly,
} from './ucscShared.ts'
import { useUcscQuery } from './useUcscQuery.ts'

import type { PslRow } from './blatQuery.ts'
import type { UcscHost } from './ucscShared.ts'

// A reference that cannot be read leaves every target gap a deletion, which is
// how the hit drew before splice sites were read, rather than failing a search
// that did find hits.
async function readSplicing(
  session: UcscHost,
  assemblyName: string,
  rows: PslRow[],
) {
  try {
    return await spliceHits(rows, referenceReader(session, assemblyName))
  } catch (e) {
    console.error('BLAT: could not read splice sites', e)
    return rows.map(row => ({ row, spliced: false }))
  }
}

const BlatDialog = observer(function BlatDialog({
  session,
  handleClose,
  initialSequence = '',
  initialAssembly = viewedAssembly(session),
}: {
  session: UcscHost
  handleClose: () => void
  // what a read, clip or selection launched this with, as FASTA
  initialSequence?: string
  initialAssembly?: string
}) {
  const query = useUcscQuery({
    session,
    handleClose,
    defaultUrl: DEFAULT_BLAT_URL,
    initialAssembly,
  })
  const { db } = query
  const [seq, setSeq] = useState(initialSequence)

  const records = parseFastaRecords(seq)
  const queryCount = records.length
  const seqError = blatQueryProblem(records)
  // an empty box disables submit without turning the field red, so the minimum
  // is checked here rather than reported above
  const submittable =
    !seqError && blatResidueCount(records) >= MINIMUM_BLAT_LENGTH

  async function handleSubmit() {
    const label = queryLabel(records)
    await query.runQuery({
      // PSL states each hit as aligned blocks in query and target coordinates,
      // which is a CIGAR alignment: converting to SAM and showing it in an
      // alignments track draws the hit's exon-like blocks, its indels, the
      // unaligned ends of the query as soft clips, and — since the submitted
      // sequence is right here — its mismatches against the reference.
      fetchResult: async fetchUcsc => {
        const rows = await fetchUcsc({
          body: buildBlatBody({ db, seq: seq.trim() }),
          parse: parseBlatResponse,
        })
        return {
          features: pslToFeatures(rows),
          // an older host has no SamAdapter; addResultTrack then falls back to
          // drawing the hits' block structure as a plain feature track
          trackConf: canRenderAlignments(session)
            ? {
                type: 'AlignmentsTrack',
                adapter: {
                  type: 'SamAdapter',
                  samText: pslToSam(
                    await readSplicing(session, query.assembly, rows),
                    parseQuerySequences(seq),
                  ),
                },
                // A handful of hits has no depth to read, so the coverage band is 45
                // pixels saying "1" over the one place the query landed. The hits
                // themselves are the answer here, unlike a sequencing pileup.
                //
                // heightMode 'grow' would also be the natural fit (the content is a
                // few hits of known size, so the fixed lane is mostly empty), but a
                // single-hit track grown to its content comes out with the read
                // clipped by the bottom edge of the view. Left off until that is
                // understood.
                displayDefaults: { showCoverage: false },
              }
            : undefined,
        }
      },
      trackIdPrefix: 'blat',
      queries: [...parseQuerySequences(seq).keys()],
      trackName:
        queryCount > 1 ? `BLAT ${label} +${queryCount - 1}` : `BLAT ${label}`,
      emptyMessage: `No BLAT hits found in ${db}`,
    })
  }

  return (
    <Dialog
      open
      // the sequence box is the dialog, and a pasted read or FASTA line wraps
      // every 40-odd bases at the default 600px — wide enough to read a
      // sequence without horizontal hunting
      maxWidth="md"
      fullWidth
      title="BLAT search (UCSC)"
      onClose={() => {
        query.close()
      }}
    >
      <DialogContent
        style={{ display: 'flex', flexDirection: 'column', gap: 12 }}
      >
        <MonospaceTextField
          label="Sequence"
          value={seq}
          onChange={event => {
            setSeq(event.target.value)
          }}
          multiline
          minRows={6}
          maxRows={14}
          autoFocus
          placeholder="Paste a DNA sequence or FASTA to locate it in the genome"
          error={!!seqError}
          helperText={
            seqError ||
            'DNA, or FASTA with up to 25 records, 25 kb each and 50 kb in total. Hits are added as a track, and listed best-first in a panel where each one is a link.'
          }
        />
        <UcscQueryFields
          session={session}
          query={query}
          urlLabel="BLAT server URL"
        />
        <UcscQueryStatus query={query} />
      </DialogContent>
      <UcscQueryActions
        query={query}
        submitDisabled={!submittable || !db}
        onSubmit={() => void handleSubmit()}
        onCancel={() => {
          query.close()
        }}
      />
    </Dialog>
  )
})

export default BlatDialog
